export const NOUN_S_ENDINGS: readonly string[] = ["ss", "us", "is", "ics", "ous", "ices", "ions", "ments", "nesses", "ities", "ances", "ences", "ers", "ors", "ons", "ists", "isms", "als", "ings", "ays", "eys", "ains", "ets", "ies"];

