/** Morphological verb test: -izes/-ated/-ified/... and -ed after a non-e letter. */
export const MORPH_VERB_RE = new RegExp("^[a-z]{3,}(?:izes|ises|ates|ifies|yzes|yses|ized|ised|ated|ified|yzed|ysed|[^e]ed)$");

/** A token is a word (style_check.py WORD_RE). */
export const WORD_RE = new RegExp("^[A-Za-z]+(?:[-'’][A-Za-z]+)*$");

/** Punctuation stripped from token edges (style_check.py PUNCT). */
export const PUNCT = ".,;:!?()[]{}\"“”'’‘`";

/** Check 3, class A sentence openers (Moreover, Furthermore, Thus, Hence, Also, ...), flagged on sight. */
export const CONN_A = new RegExp("^(?:moreover|furthermore|notably|importantly|interestingly|hence|thus(?!\\s+far)|also|besides|what is more|more importantly|most importantly|last but not least|needless to say|on top of that|significantly)\\b(?!\\s+(?:larger|smaller|more|less|better|worse|higher|lower))", 'i');

/** Check 3, class B sentence openers (In addition, Additionally, Therefore, Consequently). */
export const CONN_B = new RegExp("^(?:in addition|additionally|therefore|consequently|as a consequence)\\b", 'i');

/** Check 3, stock filler (It is worth noting that, ...). */
export const STOCK_RE = new RegExp("\\bit (?:is|should be|must be|can be|has to be|may be|was) (?:worth (?:noting|mentioning|pointing out|emphasi[sz]ing|stressing|remembering)|(?:important|interesting|crucial|essential|necessary|useful|instructive|noteworthy|worthwhile) to (?:note|mention|point out|stress|emphasi[sz]e|remember|recall|keep in mind|notice|highlight)|noted|mentioned|emphasi[sz]ed|stressed|pointed out|recalled|remembered|highlighted)\\s+(?:here\\s+)?that\\b|\\bit is noteworthy that\\b|\\bit (?:is|becomes) (?:evident|obvious|apparent) that\\b|\\bneedless to say\\b|\\bit goes without saying\\b", 'gi');

/** Numbers that are labels (Fig. 3, Sec. II, Run 2), removed before the number test. */
export const LABEL_NUM_RE = new RegExp("(?:\\b(?:Figs?|Figures?|figures?|Tabs?|Tables?|tables?|Secs?|Sects?|Sections?|sections?|Eqs?|Eqns?|Equations?|equations?|Refs?|Apps?|Appendix|Appendices|appendix|Chapters?|Ch|Models?|Runs?|Cases?|Scenarios?|Benchmarks?|Steps?|Panels?|Points?|Regions?|Categor(?:y|ies)|Options?|Versions?|Algorithms?|Lines?|Rows?|Columns?|Layers?|Iterations?|Epochs?|Phase|Stage|Level|Model)\\.?\\s*~?\\(?\\s*(?:N|\\d+|[IVX]+|[A-H])\\b\\)?(?:\\s*(?:,|and|&|–|-|to|or)\\s*\\(?(?:N|\\d+|[IVX]+|[A-H])\\b\\)?)*)", 'g');

/** Years, removed before the number test. */
export const YEAR_RE = new RegExp("\\b(?:19|20)\\d\\d\\b", 'g');

/** A numeral. */
export const NUM_TOKEN_RE = new RegExp("(?<![A-Za-z0-9_])\\d+(?:[.,]\\d+)*(?![A-Za-z0-9])", 'g');

/** A spelled-out quantity (three, twice, factor of, percent, ...). */
export const SPELLED_NUM_RE = new RegExp("\\b(?:two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|twenty|thirty|forty|fifty|hundred|thousand|million|billion|twice|thrice|half|halve[sd]?|double[sd]?|doubling|tripled?|quadrupled?|tenfold|twofold|threefold|factor of|orders? of magnitude|percent|per cent|dozen)\\b", 'gi');

/** Statistics words that license *significant*. */
export const STAT_RE = new RegExp("\\b(?:statistical(?:ly)?|significance|sigma|σ|p-?values?|confidence|excess(?:es)?|deviations?|discovery|evidence|hypothes[ie]s|fluctuations?|test statistic)\\b", 'gi');

/** CL / CLs (case-sensitive). */
export const STAT_CS_RE = new RegExp("\\bCLs?\\b", 'g');

/** It was found that ... (check 10). */
export const IT_PASSIVE_RE = new RegExp("\\bit (?:is|was|has been|had been|can be|could be|will be|may be) (?:found|shown|observed|seen|demonstrated|concluded|determined|verified|confirmed|expected|believed|assumed|argued|known|estimated|suggested|proposed) that\\b", 'gi');

/** in order to / in order for (check 3). */
export const IN_ORDER_RE = new RegExp("\\bin order (?:to|for)\\b", 'gi');

