/**
 * Check 5, hype and intensifiers: [pattern, kind, alternative]. Kinds: `always` (flag on sight),
 * `comparative` (not after more/less/as), `number` (not in a sentence with a number), `stat` (not in a
 * sentence with a number or a statistics word).
 */
export const HYPE: ReadonlyArray<readonly [string, 'always' | 'comparative' | 'number' | 'stat', string]> = [
  ["novel(?:ty)?", "always", "new, or say what is new"],
  ["remarkabl[ey]", "always", "drop it, or give the number"],
  ["promising", "always", "say what it achieves"],
  ["crucial(?:ly)?", "always", "important, or say why it matters"],
  ["unprecedented", "always", "give the comparison"],
  ["groundbreaking|ground-breaking|revolutionary|game-?chang(?:ing|er)", "always", "drop it"],
  ["state[- ]of[- ]the[- ]art", "always", "name the method and give the comparison"],
  ["cutting[- ]edge", "always", "drop it"],
  ["paramount|pivotal|invaluable", "always", "important, or say why"],
  ["excellent|outstanding|impressive|superb|exceptional(?:ly)?|extraordinary|tremendous(?:ly)?|spectacular", "always", "give the number"],
  ["powerful", "comparative", "give the comparison (more powerful than ...)"],
  ["dramatic(?:ally)?", "number", "give the number"],
  ["very", "number", "drop it, or give the number"],
  ["extremely|incredibly|vastly|hugely|enormously|immensely|greatly", "number", "drop it, or give the number"],
  ["highly", "number", "drop it, or give the number"],
  ["significant(?:ly)?", "stat", "give the number, or use *substantial* or *large*"],
];
